// Parser for `agents/*.md` — the agent vertical of the capability graph.
//
// The source of truth is the markdown frontmatter, not `registries/agents.json`:
// that file's own header says it is generated by
// `scripts/gen-agent-registry.sh` and must not be hand-edited. Reading the
// generated copy would show the console a snapshot that can be stale relative
// to the files an operator is actually looking at; drift between the two is a
// separate concern, and the integrity checks already own it.
//
// Read-only, and deliberately so — see the note on AgentEntity in types.ts.

import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';

import { parseCommaList, parseMarkdownWithFrontmatter } from './frontmatter';
import { loadGraph, resolveAgentRelations } from './relations';
import type { AgentEntity } from './types';

/**
 * The alias is NOT a frontmatter key. `scripts/gen-agent-registry.sh` extracts
 * it from the literal text `Alias: <slug>` inside the frontmatter block —
 * today it lives at the end of each agent's `description:`. This mirrors that
 * rule exactly, and on purpose: a second interpretation would put a different
 * alias in the console than the one the generated registry and the slash
 * commands carry, and the alias is what an operator actually types.
 *
 * Reading an `alias:` key would have been the obvious guess. It would also have
 * returned null for all 22 agents, which is the same fixed-empty-field defect
 * this vertical exists to stop repeating.
 */
function extractAlias(frontmatterBlock: string): string | null {
  const match = /alias:[ \t]*([a-z0-9-]+)/i.exec(frontmatterBlock);
  const alias = match?.[1]?.trim();
  return alias && alias !== 'null' ? alias : null;
}

function toRelativePath(basePath: string, absolute: string): string {
  return path.relative(basePath, absolute).split(path.sep).join('/');
}

/**
 * Parses every `agents/*.md`. A malformed file yields a `status: 'error'`
 * entity with `parseError` set rather than throwing — one bad file must not
 * blank the whole page, the same contract the skills parser keeps.
 */
export function parseAgents(basePath: string): AgentEntity[] {
  const agentsDir = path.join(basePath, 'agents');
  if (!existsSync(agentsDir)) return [];

  const files = readdirSync(agentsDir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.md'))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));

  const graph = loadGraph(basePath);
  const result: AgentEntity[] = [];

  for (const file of files) {
    const absolute = path.join(agentsDir, file);
    const id = file.replace(/\.md$/, '');
    const sourcePaths = [toRelativePath(basePath, absolute)];
    const updatedAt = statSync(absolute).mtime.toISOString();

    try {
      const { block, data, body } = parseMarkdownWithFrontmatter(readFileSync(absolute, 'utf8'));
      const relations = resolveAgentRelations(graph, id, body);

      result.push({
        id,
        kind: 'agent',
        name: typeof data.name === 'string' && data.name.trim() !== '' ? data.name : id,
        status: 'active',
        sourcePaths,
        updatedAt,
        description: typeof data.description === 'string' ? data.description : '',
        alias: extractAlias(block),
        tools: parseCommaList(data.tools),
        model: typeof data.model === 'string' ? data.model : '',
        tier: typeof data.tier === 'string' ? data.tier : '',
        usesSkills: relations.usesSkills,
        routedDomains: relations.routedDomains,
        capabilityIds: relations.capabilityIds,
      });
    } catch (err) {
      result.push({
        id,
        kind: 'agent',
        name: id,
        status: 'error',
        sourcePaths,
        updatedAt,
        description: '',
        alias: null,
        tools: [],
        model: '',
        tier: '',
        usesSkills: [],
        routedDomains: [],
        capabilityIds: [],
        parseError: (err as Error).message,
      });
    }
  }

  return result;
}
